def combine(items):
    totals = {}
    for item in items:
        quantity = item['quantity']
        if quantity == 0:
            continue

        name = ' '.join(item['name'].lower().split())
        unit = item['unit'].strip().lower()

        if unit in ('g', 'gram', 'grams'):
            output_unit = 'g'
        elif unit in ('kg', 'kilogram', 'kilograms'):
            output_unit = 'g'
            quantity *= 1000
        elif unit in ('ml', 'millilitre', 'millilitres'):
            output_unit = 'ml'
        elif unit in ('l', 'litre', 'litres'):
            output_unit = 'ml'
            quantity *= 1000
        elif unit in ('', 'each', 'item', 'items'):
            output_unit = 'each'
        else:
            output_unit = unit

        key = (name, output_unit)
        totals[key] = totals.get(key, 0) + quantity

    return [
        {'name': name, 'quantity': round(totals[(name, unit)], 6), 'unit': unit}
        for name, unit in sorted(totals)
    ]

